"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["17735"],{82480(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.peso_area_enem.area_repetida","status":422,"titulo":"\xc1rea informada mais de uma vez"},"descricao":{"codigo":"uniplus.configuracao.peso_area_enem.area_repetida","requisitos":["UNI-REQ-0174"],"oQueAconteceu":["Cada \xe1rea do ENEM tem um \xfanico peso por linha de pesos, como no Anexo I da Resolu\xe7\xe3o n\xba 805/2024/Consepe, da Unifesspa, em que cada grupo de \xe1rea d\xe1 um peso a cada \xe1rea. A lista `areas` traz o mesmo c\xf3digo de \xe1rea em mais de um item, e a API n\xe3o escolhe qual dos pesos vale (UNI-REQ-0174).","A recusa vem na lista `errors` da resposta, com `field` igual a `areas[i].codigo`, em que `i` \xe9 a posi\xe7\xe3o da segunda ocorr\xeancia da \xe1rea, come\xe7ando em zero. O peso e o corte do item repetido tamb\xe9m s\xe3o conferidos pelas regras da pr\xf3pria \xe1rea, mas n\xe3o entram na linha. As demais recusas do corpo v\xeam na mesma resposta, e nada \xe9 gravado. Na atualiza\xe7\xe3o, o corpo \xe9 conferido antes da busca da linha: um `{id}` que n\xe3o existe s\xf3 responde como n\xe3o encontrado quando o corpo \xe9 v\xe1lido."],"comoResolver":["Deixe cada uma das cinco \xe1reas em um \xfanico item da lista e envie de novo."],"ondeAparece":["Cadastro dos pesos por \xe1rea do ENEM","Atualiza\xe7\xe3o dos pesos por \xe1rea do ENEM"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Peso area enem"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"38e6e984f8a69f1cdfcd140295a410206c687849"}}')}}]);